const puppeteer = require('puppeteer');
const path = require('path');

(async () => {
  console.log('Launching browser...');
  const browser = await puppeteer.launch({
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });
  const page = await browser.newPage();

  // High resolution to ensure the output is high-quality like a poster
  await page.setViewport({ width: 1200, height: 1600, deviceScaleFactor: 2 });

  console.log('Navigating to poster.html...');
  const filePath = 'file://' + path.resolve(__dirname, 'poster.html');
  await page.goto(filePath, { waitUntil: 'networkidle0' });

  console.log('Waiting for render complete signal...');
  try {
    await page.waitForFunction('window.RENDER_COMPLETE === true', { timeout: 15000 });
  } catch(e) {
    console.log('Timeout waiting for signal, capturing anyway...');
  }

  console.log('Capturing screenshot...');
  await page.screenshot({ path: '/app/output/final_poster.png' });
  console.log('Screenshot saved to /app/output/final_poster.png');

  await browser.close();
})();

